"use client"

import { useEffect } from "react"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { useAppSelector } from "@/redux/hooks"
import { useLinkGithubOverlayState } from "@/hooks/zustand/overlay/hooks"

/** Session-storage key marking that the soft GitHub-link prompt already fired this session. */
const SESSION_PROMPT_KEY = "linkGithubPrompted"

/** Props for {@link GithubLinkGate}. */
export type GithubLinkGateProps = WithClassNames<undefined>

/**
 * Soft gate that nudges authenticated learners to link their GitHub account.
 *
 * Rendered inside the learn layout. When the signed-in user has no `githubUsername`, it opens
 * the global {@link LinkGithubModal} once per browser session (soft: the user may close it and
 * keep learning; it re-prompts on the next session). Renders nothing — className is accepted
 * for API conformance but not applied.
 * @param props - {@link GithubLinkGateProps}
 */
export const GithubLinkGate = ({ className }: GithubLinkGateProps) => {
    // className accepted for API conformance; this component renders null (side-effect only)
    void className
    // only authenticated users can link; unauthenticated visitors never see the prompt
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    // the resolved current user — carries githubUsername once the `me` query populates it
    const user = useAppSelector((state) => state.user.user)
    // global overlay handle for the link-GitHub modal (rendered by ModalContainer)
    const { setOpen } = useLinkGithubOverlayState()

    useEffect(() => {
        // wait until we actually know who the user is before deciding to prompt
        if (!authenticated || !user) {
            return
        }
        // already linked → nothing to do
        if (user.githubUsername) {
            return
        }
        // guard against SSR where sessionStorage is unavailable
        if (typeof window === "undefined") {
            return
        }
        // soft behaviour: prompt at most once per session so closing it isn't nagging
        if (window.sessionStorage.getItem(SESSION_PROMPT_KEY)) {
            return
        }
        // mark first so a re-render (or fast unmount/mount) can't double-open the modal
        window.sessionStorage.setItem(SESSION_PROMPT_KEY, "1")
        // open the link-GitHub modal
        setOpen(true)
    }, [
        authenticated,
        user,
        setOpen,
    ])

    return null
}

"use client"

import React, { useCallback } from "react"
import { useTranslations } from "next-intl"
import { usePaymentOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useQueryCoursePricePreviewSwr } from "@/hooks/swr/api/graphql/queries/useQueryCoursePricePreviewSwr"
import { PaymentFlow } from "@/modules/types/payment"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { _TrialConversionStrip } from "./component"

/** Props for {@link TrialConversionStrip}. */
export interface TrialConversionStripProps {
    /** Course id (raw uuid) — prices the enroll offer. */
    courseId: string
    /** FREE lessons the trial viewer hasn't read yet — powers the goal-gradient line. */
    freeLessonsRemaining: number
    /** Where this strip sits inside its parent. */
    classNames?: Array<AllowedClassName>
}

/**
 * Trial → enroll conversion strip on the content-home — the CONNECTED half: it fetches the
 * viewer's pre-checkout price (SWR), owns the payment-overlay handler, resolves the loss-aversion
 * copy (goal-gradient when free lessons remain, else the generic pitch), and hands it all to the
 * presentational {@link _TrialConversionStrip}. Rendered ONLY for a trial (not-yet-enrolled)
 * learner — the parent gates it. See `design/storybook/architecture/split.md`.
 */
export const TrialConversionStrip = ({
    courseId,
    freeLessonsRemaining,
    classNames,
}: TrialConversionStripProps) => {
    const t = useTranslations()
    const { open } = usePaymentOverlayState()
    const priceSwr = useQueryCoursePricePreviewSwr(courseId)

    /** Open the shared payment modal in the course-enroll flow. */
    const onEnroll = useCallback(
        () => open({ flow: PaymentFlow.CourseEnroll }),
        [open],
    )

    // goal-gradient: when free lessons remain, frame by "N left to read" (near a
    // milestone) rather than the generic pitch.
    const description = freeLessonsRemaining > 0
        ? t("courseContents.trial.descRemaining", { remaining: freeLessonsRemaining })
        : t("courseContents.trial.desc")

    return (
        <_TrialConversionStrip
            title={t("courseContents.trial.title")}
            description={description}
            cta={t("courseContents.trial.cta")}
            price={priceSwr.data}
            isSkeleton={priceSwr.isLoading}
            onEnroll={onEnroll}
            classNames={classNames}
        />
    )
}

"use client"

import React, { useState } from "react"
import { Link, cn } from "@heroui/react"
import { SealCheckIcon } from "@phosphor-icons/react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { getTimeAgoLabel, getTimeAgoMessage } from "@/modules/dayjs"
import { pathConfig } from "@/resources/path"
import { EntityLink } from "@/components/blocks/feed/EntityLink"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import { ReactionBar } from "./ReactionBar"
import { CommentComposer } from "./CommentComposer"
import { ReactionType, type CommentNode } from "@/modules/api/graphql/queries/types/discussion"
/** Callbacks shared down the comment tree. */
export interface CommentItemCallbacks {
    /** Post a reply under `parentId`. */
    onReply: (parentId: string, body: string) => void
    /** Edit a comment body (author only). */
    onEdit: (commentId: string, body: string) => void
    /** Soft-delete a comment (author only). */
    onDelete: (commentId: string) => void
    /** React to a comment (null removes the reaction). */
    onReactComment: (commentId: string, type: ReactionType | null) => void
    /** Lazily load the replies of `parentId`. */
    onLoadReplies: (parentId: string) => void
}

/** Props for {@link CommentItem}. */
export interface CommentItemProps extends CommentItemCallbacks {
    /** The comment to render. */
    comment: CommentNode
    /** Current viewer id (drives owner-only actions); null when unknown. */
    currentUserId: string | null
    /** Nesting depth (controls visual indentation). */
    depth: number
    /** Replies keyed by parent comment id (lazily populated by the container). */
    repliesByParent: Record<string, Array<CommentNode>>
}

/**
 * A single threaded comment with author, reactions, owner actions, reply box, and its
 * recursively-rendered replies. Visual indentation is capped so deep threads stay readable.
 *
 * Presentational: owns only transient UI state (editing/replying/expanded); persistence is
 * delegated via the {@link CommentItemCallbacks}.
 * @param props - {@link CommentItemProps}
 */
export const CommentItem = ({
    comment,
    currentUserId,
    depth,
    repliesByParent,
    onReply,
    onEdit,
    onDelete,
    onReactComment,
    onLoadReplies}: CommentItemProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    // transient per-comment UI state
    const [replying, setReplying] = useState(false)
    const [editing, setEditing] = useState(false)
    const [expanded, setExpanded] = useState(false)

    const isOwner = currentUserId !== null && currentUserId === comment.author.id
    const replies = repliesByParent[comment.id] ?? []

    // expand/collapse the reply subtree, loading it on first expand
    const toggleReplies = () => {
        const next = !expanded
        setExpanded(next)
        if (next) {
            onLoadReplies(comment.id)
        }
    }

    return (
        <div
            className={cn("flex flex-col gap-2",
                // indent nested replies with a guide border, capped after a few levels
                depth > 0 ? "border-l border-default pl-3 @app-sm:pl-4" : undefined)}
        >
            <div className="flex gap-3">
                <UserAvatar
                    size="sm"
                    username={comment.author.username}
                    avatar={comment.author.avatar}
                    className="mt-0 shrink-0"
                />
                <div className="flex min-w-0 flex-1 flex-col gap-2">
                    {/* author + founder badge + timestamp header */}
                    <div className="flex flex-wrap items-center gap-2">
                        <EntityLink
                            label={comment.author.username}
                            onPress={() => router.push(
                                pathConfig().locale(locale).profile(comment.author.username).build(),
                            )}
                            className="text-sm"
                        />
                        {comment.isFounderAuthor ? (
                            <SealCheckIcon
                                weight="fill"
                                aria-label={t("discussion.founderBadge")}
                                className="size-3.5 shrink-0 text-accent-soft-foreground"
                            />
                        ) : null}
                        <span className="text-xs text-muted">
                            {getTimeAgoLabel(getTimeAgoMessage(comment.createdAt), t)}
                        </span>
                        {comment.editedAt ? (
                            <span className="text-xs text-muted">{t("discussion.edited")}</span>
                        ) : null}
                    </div>

                    {/* body, edit form, or deleted placeholder */}
                    {comment.isDeleted ? (
                        <div className="text-sm italic text-muted">{t("discussion.deletedPlaceholder")}</div>
                    ) : editing ? (
                        <CommentComposer
                            initialValue={comment.body}
                            submitLabel={t("common.save")}
                            onCancel={() => setEditing(false)}
                            onSubmit={(body) => {
                                onEdit(comment.id, body)
                                setEditing(false)
                            }}
                        />
                    ) : (
                        <div className="whitespace-pre-wrap text-sm leading-relaxed text-foreground">
                            {comment.body}
                        </div>
                    )}

                    {/* action row: reactions + reply + owner edit/delete */}
                    {!comment.isDeleted && !editing ? (
                        <div className="flex flex-wrap items-center gap-3">
                            <ReactionBar
                                summary={comment.reactions}
                                onReact={(type) => onReactComment(comment.id, type)}
                            />
                            <Link
                                className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                                onPress={() => setReplying((prev) => !prev)}
                            >
                                {t("discussion.reply")}
                            </Link>
                            {isOwner ? (
                                <>
                                    <Link
                                        className="cursor-pointer text-xs font-medium text-muted hover:text-foreground"
                                        onPress={() => setEditing(true)}
                                    >
                                        {t("common.edit")}
                                    </Link>
                                    <Link
                                        className="cursor-pointer text-xs font-medium text-muted hover:text-danger-soft-foreground"
                                        onPress={() => onDelete(comment.id)}
                                    >
                                        {t("common.delete")}
                                    </Link>
                                </>
                            ) : null}
                        </div>
                    ) : null}

                    {/* reply composer */}
                    {replying ? (
                        <CommentComposer
                            placeholder={t("discussion.replyPlaceholder")}
                            submitLabel={t("discussion.reply")}
                            onCancel={() => setReplying(false)}
                            onSubmit={(body) => {
                                onReply(comment.id, body)
                                setReplying(false)
                                // surface the new reply immediately by expanding the subtree
                                setExpanded(true)
                                onLoadReplies(comment.id)
                            }}
                        />
                    ) : null}

                    {/* replies toggle + recursive subtree */}
                    {comment.replyCount > 0 ? (
                        <Link
                            className="cursor-pointer self-start text-xs font-medium text-accent-soft-foreground hover:underline underline-offset-4 decoration-[var(--separator-tertiary)]"
                            onPress={toggleReplies}
                        >
                            {expanded
                                ? t("discussion.hideReplies")
                                : t("discussion.viewReplies", { count: comment.replyCount })}
                        </Link>
                    ) : null}

                    {expanded && replies.length > 0 ? (
                        <div className="mt-1 flex flex-col gap-3">
                            {replies.map((reply) => (
                                <CommentItem
                                    key={reply.id}
                                    comment={reply}
                                    currentUserId={currentUserId}
                                    depth={depth + 1}
                                    repliesByParent={repliesByParent}
                                    onReply={onReply}
                                    onEdit={onEdit}
                                    onDelete={onDelete}
                                    onReactComment={onReactComment}
                                    onLoadReplies={onLoadReplies}
                                />
                            ))}
                        </div>
                    ) : null}
                </div>
            </div>
        </div>
    )
}

"use client"

import React from "react"
import { cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { REACTIONS } from "./constants"
import { ReactionEmoji } from "./ReactionEmoji"
import { ReactionType } from "@/modules/api/graphql/queries/types/discussion"

/** Props for {@link FacebookReactionSelector}. */
export interface FacebookReactionSelectorProps {
    /** The viewer's current reaction, highlighted in the bar (null = none). */
    active?: ReactionType | null
    /** Called with the picked emotion. */
    onSelect: (type: ReactionType) => void
}

/**
 * Facebook-style reaction picker bar — the six emotions in a row, each scaling up and
 * lifting with its name floating above on hover, popping in with a slight stagger when
 * the bar appears.
 *
 * Reimplemented natively (native emoji glyphs + CSS keyframe `reactionPop`, NO third-party
 * reaction library) so it follows our design tokens + dark mode. The pop-in animation sits
 * on the button while the hover scale sits on an inner span, so the two transforms never
 * clash. Render inside the reaction Popover; selection is delegated via `onSelect`.
 *
 * @param props - {@link FacebookReactionSelectorProps}
 */
export const FacebookReactionSelector = ({ active, onSelect}: FacebookReactionSelectorProps) => {
    const t = useTranslations()

    return (
        <div className={"flex items-center gap-1"}>
            {REACTIONS.map((reaction, index) => {
                const label = t(reaction.labelKey)
                return (
                    <button
                        key={reaction.type}
                        type="button"
                        aria-label={label}
                        aria-pressed={active === reaction.type}
                        onClick={() => onSelect(reaction.type)}
                        // each emoji bounces in slightly after the previous one
                        style={{ animationDelay: `${index * 35}ms` }}
                        className={cn(
                            "group/fbreact relative flex animate-[reactionPop_220ms_cubic-bezier(0.34,1.56,0.64,1)_both]",
                            "cursor-pointer items-center justify-center rounded-full p-1 outline-none",
                            "focus-visible:ring-2 focus-visible:ring-accent",
                            active === reaction.type ? "bg-accent-soft" : undefined,
                        )}
                    >
                        {/* reaction name floats above on hover, in the style of Facebook */}
                        <span className="pointer-events-none absolute -top-7 left-1/2 -translate-x-1/2 scale-90 whitespace-nowrap rounded-full bg-foreground px-2 py-0 text-[10px] font-medium text-background opacity-0 transition-all duration-150 group-hover/fbreact:scale-100 group-hover/fbreact:opacity-100">
                            {label}
                        </span>
                        {/* emoji scales up + lifts on hover (transform isolated from the pop-in) */}
                        <span className="block origin-bottom transition-transform duration-150 ease-out group-hover/fbreact:-translate-y-1 group-hover/fbreact:scale-[1.45]">
                            <ReactionEmoji descriptor={reaction} size="md" />
                        </span>
                    </button>
                )
            })}
        </div>
    )
}

import React from "react"

/** Props for {@link AuroraRibbon}. */
interface AuroraRibbonProps {
    top: number
    duration: number
    delay: number
}

/** One soft, blurred ribbon swaying slowly, tinted by the accent color. */
const AuroraRibbon = ({
    top,
    duration,
    delay,
}: AuroraRibbonProps) => (
    <div
        className="ambient-aurora absolute inset-x-[-20%]"
        style={{
            top: `${top}%`,
            height: "45%",
            filter: "blur(40px)",
            opacity: 0.35,
            background:
                "linear-gradient(90deg, transparent, color-mix(in oklch, var(--accent) 55%, transparent), transparent)",
            animation: `auroraDrift ${duration}s ease-in-out infinite ${delay}s`,
        }}
    />
)

/** Soft moving aurora ribbons, tinted by the accent color. */
export const AuroraEffect = () => (
    <>
        <AuroraRibbon top={-10} duration={22} delay={0} />
        <AuroraRibbon top={15} duration={28} delay={4} />
        <AuroraRibbon top={2} duration={18} delay={8} />
    </>
)

import React from "react"
import {
    useSeededParticles,
} from "../useSeededParticles"

/** Props for {@link BubblesEffect}. */
interface BubblesEffectProps {
    /** Particle count. */
    count?: number
}

/** Hollow bubbles rising from the bottom edge with a gentle wobble, tinted by the accent color. */
export const BubblesEffect = ({ count = 30 }: BubblesEffectProps) => {
    const particles = useSeededParticles(count, 37)
    return (
        <>
            <div
                className="absolute inset-x-0 bottom-0 h-1/3"
                style={{
                    background:
                        "radial-gradient(120% 80% at 50% 120%, color-mix(in oklch, var(--accent) 22%, transparent), transparent 70%)",
                }}
            />
            {particles.map((p) => (
                <span
                    key={p.index}
                    className="ambient-bubble absolute bottom-0 rounded-full"
                    style={{
                        left: `${p.left}%`,
                        width: `${p.size * 2}px`,
                        height: `${p.size * 2}px`,
                        border: "1.5px solid color-mix(in oklch, var(--accent) 70%, transparent)",
                        background: "color-mix(in oklch, var(--accent) 12%, transparent)",
                        ["--drift" as string]: `${p.drift}px`,
                        animation: `bubbleRise ${p.duration + 3}s ease-in infinite ${p.delay}s`,
                        opacity: 0,
                    }}
                />
            ))}
        </>
    )
}

