import React from "react"

/** Props for {@link WaveLayer}. */
interface WaveLayerProps {
    duration: number
    opacity: number
    bottom: number
    amplitude: number
}

/** One tiled, horizontally-scrolling wave layer (two copies side by side loop seamlessly). */
const WaveLayer = ({
    duration,
    opacity,
    bottom,
    amplitude,
}: WaveLayerProps) => (
    <div
        className="ambient-wave absolute left-0 w-[200%]"
        style={{
            bottom: `${bottom}px`,
            height: "56px",
            opacity,
            animation: `waveDrift ${duration}s linear infinite`,
        }}
    >
        <svg viewBox="0 0 240 40" preserveAspectRatio="none" className="block h-full w-full">
            <path
                d={`M0,${20 - amplitude} c15,${amplitude * -1.4} 45,${amplitude * -1.4} 60,0 c15,${amplitude * 1.4} 45,${amplitude * 1.4} 60,0 c15,${amplitude * -1.4} 45,${amplitude * -1.4} 60,0 c15,${amplitude * 1.4} 45,${amplitude * 1.4} 60,0 L240,40 L0,40 Z`}
                fill="var(--accent)"
            />
        </svg>
    </div>
)

/** Layered waves drifting horizontally at the bottom edge, tinted by the accent color. */
export const WaveEffect = () => (
    <>
        <div
            className="absolute inset-x-0 bottom-0 h-1/2"
            style={{
                background:
                    "radial-gradient(120% 80% at 50% 120%, color-mix(in oklch, var(--accent) 28%, transparent), transparent 70%)",
            }}
        />
        <WaveLayer duration={9} opacity={0.35} bottom={0} amplitude={10} />
        <WaveLayer duration={6.5} opacity={0.5} bottom={6} amplitude={8} />
    </>
)

"use client"

import React from "react"
import { useAccountMenuOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useAppSelector } from "@/redux/hooks"
import type { WithClassNames } from "@/modules/types/base/class-name"
import { _AccountMenuDropdown } from "./component"

/** Props for {@link AccountMenuDropdown}. */
export type AccountMenuDropdownProps = WithClassNames<{
    /** Optional class applied to the dropdown container. */
    menuContainer?: string
}>

/**
 * AccountMenuDropdown — navbar account menu — the CONNECTED half: owns the
 * dropdown overlay open/close state and reads whether the viewer is signed
 * in (decides {@link import("./UserSummary").UserSummary} vs
 * {@link import("./AuthActions").AuthActions}); every other section wires
 * its own data. See `design/storybook/architecture/split.md`.
 * @param props - optional class-name overrides
 */
export const AccountMenuDropdown = (props: AccountMenuDropdownProps) => {
    const { classNames } = props
    const { isOpen, setOpen } = useAccountMenuOverlayState()
    const user = useAppSelector((state) => state.user.user)

    return (
        <_AccountMenuDropdown
            isOpen={isOpen}
            onOpenChange={setOpen}
            isAuthenticated={Boolean(user)}
            classNames={classNames}
        />
    )
}

"use client"

import React from "react"
import { Button, Typography } from "@heroui/react"
import {
    CaretUpIcon,
    SealCheckIcon,
} from "@phosphor-icons/react"
import { useTranslations } from "next-intl"
import { UserAvatar } from "@/components/blocks/identity/UserAvatar"
import { AvatarGroup, type AvatarGroupItem } from "@/components/composites/lists/AvatarGroup"
import { FollowButton } from "@/components/blocks/community/FollowButton"

/** Props for {@link QaConversationHeader}. */
export interface QaConversationHeaderProps {
    /** The asker (whose question opens the conversation). */
    asker: {
        /** Asker username (drives avatar fallback). */
        username: string
        /** Asker display name; falls back to username. */
        displayName?: string | null
        /** Asker avatar url, or null. */
        avatar?: string | null
    }
    /** Whether the asker is the founder (drives the verified badge). */
    isFounderAsker?: boolean
    /** Distinct people who have answered — shown as an overlapping avatar group. */
    participants: Array<AvatarGroupItem>
    /** Total answers (top-level + replies) — the "N replies" line. */
    replyCount: number
    /** Collapse the conversation back to its inbox row. */
    onCollapse: () => void
    /** Show a follow control for the asker (hidden for one's own question / signed out). */
    canFollow?: boolean
    /** Whether the viewer currently follows the asker. */
    isFollowing?: boolean
    /** Toggle following the asker; the parent owns the `setFollow` mutation. */
    onToggleFollow?: () => void
    /** True while the follow toggle is in flight. */
    isFollowPending?: boolean
}

/**
 * Header of an opened course-Q&A conversation: a collapse control, the asker's
 * identity (avatar + name + founder badge), and — on the right — who has joined in
 * (an {@link AvatarGroup} of distinct answerers) plus the answer count. When nobody
 * has answered yet it shows a gentle, honest nudge inviting the viewer to be first,
 * turning the empty state into a social prompt rather than a dead end.
 *
 * Presentational: identity + participants + follow state arrive via props; the parent
 * owns the `setFollow` mutation and hides the control on one's own question / when signed out.
 *
 * @param props - {@link QaConversationHeaderProps}
 */
export const QaConversationHeader = ({
    asker,
    isFounderAsker,
    participants,
    replyCount,
    onCollapse,
    canFollow = false,
    isFollowing = false,
    onToggleFollow,
    isFollowPending = false}: QaConversationHeaderProps) => {
    const t = useTranslations()
    const displayName = asker.displayName || asker.username
    const hasAnswers = replyCount > 0

    return (
        <div className={"flex flex-wrap items-center justify-between gap-3 border-b border-default pb-3"}>
            {/* collapse + asker identity + follow */}
            <div className="flex min-w-0 items-center gap-2">
                <Button
                    isIconOnly
                    size="sm"
                    variant="tertiary"
                    aria-label={t("courseQa.collapse")}
                    onPress={onCollapse}
                >
                    <CaretUpIcon aria-hidden className="size-4" />
                </Button>
                <UserAvatar
                    size="sm"
                    username={asker.username}
                    avatar={asker.avatar}
                    seed={asker.username}
                    className="shrink-0"
                />
                <div className="flex min-w-0 items-center gap-2">
                    <Typography type="body-sm" weight="semibold" className="truncate">
                        {t("courseQa.askedBy", { name: displayName })}
                    </Typography>
                    {isFounderAsker ? (
                        <SealCheckIcon
                            weight="fill"
                            aria-label={t("courseQa.founderBadge")}
                            className="size-3.5 shrink-0 text-accent-soft-foreground"
                        />
                    ) : null}
                </div>
                {/* follow the asker — quiet so it never competes with the composer's primary */}
                {canFollow ? (
                    <span className="ml-1">
                        <FollowButton
                            quiet
                            following={isFollowing}
                            isPending={isFollowPending}
                            onToggle={onToggleFollow}
                        />
                    </span>
                ) : null}
            </div>

            {/* who joined in + answer count, or an invite-to-answer nudge */}
            {hasAnswers ? (
                <div className="flex shrink-0 items-center gap-2">
                    {participants.length > 0 ? (
                        <AvatarGroup items={participants} max={4} />
                    ) : null}
                    <Typography type="body-xs" color="muted">
                        {t("courseQa.replyCount", { count: replyCount })}
                    </Typography>
                </div>
            ) : (
                <Typography type="body-xs" color="muted" className="shrink-0">
                    {t("courseQa.beFirstToAnswer")}
                </Typography>
            )}
        </div>
    )
}

import React from "react"
import { Dropdown, Label } from "@heroui/react"
import { TranslateIcon } from "@phosphor-icons/react"
import { Button } from "@/components/atoms/buttons/Button"
import type { NavbarLanguageOption } from "../types"

/** Props for {@link NavbarLanguageMenu}. */
export interface NavbarLanguageMenuProps {
    languages: Array<NavbarLanguageOption>
    activeLocale: string
    onLocaleChange: (code: string) => void
}

/**
 * Locale picker — raw HeroUI `Dropdown` (see file header: no atom here supports a
 * single-select CHECK indicator). Shared verbatim by the desktop icon row and the
 * mobile drawer row so the two never drift.
 */
export const NavbarLanguageMenu = ({ languages, activeLocale, onLocaleChange }: NavbarLanguageMenuProps) => (
    <Dropdown>
        <Button
            isIconOnly
            variant="ghost"
            prefixIcon={TranslateIcon}
            ariaLabel="Language"

        />
        <Dropdown.Popover>
            <Dropdown.Menu
                aria-label="Language"
                selectionMode="single"
                selectedKeys={new Set([activeLocale])}
                onSelectionChange={(keys) => {
                    if (keys === "all") return
                    const next = [...keys][0]
                    if (next != null) onLocaleChange(String(next))
                }}

            >
                <Dropdown.Section>
                    {languages.map((language) => (
                        <Dropdown.Item
                            key={language.code}
                            id={language.code}
                            textValue={language.label}

                        >
                            <Dropdown.ItemIndicator />
                            <Label>{language.label}</Label>
                        </Dropdown.Item>
                    ))}
                </Dropdown.Section>
            </Dropdown.Menu>
        </Dropdown.Popover>
    </Dropdown>
)

import React from "react"
import { Switch as HeroSwitch } from "@heroui/react"
import { MoonIcon, SunIcon } from "@phosphor-icons/react"
import { Box } from "@/components/frames/Box"

/** Props for {@link NavbarThemeSwitch}. */
export interface NavbarThemeSwitchProps {
    isDarkMode: boolean
    onThemeToggle: (isDark: boolean) => void
}

/**
 * Dark/light toggle — raw HeroUI `Switch` (see file header: `ChoiceSwitch` has no
 * icon-in-thumb slot). Shared verbatim by the desktop row and the mobile drawer row.
 */
export const NavbarThemeSwitch = ({ isDarkMode, onThemeToggle }: NavbarThemeSwitchProps) => (
    <Box
        as="span"
        identity={{ tier: "block", component: "NavbarThemeSwitch" }}
        principle="icon-text"
        explain="Theme thumb glyph rides inside the switch — not name-handle, because this is not a person identity pair; not label-field, because neither side is a form label."
    >
        <HeroSwitch
            isSelected={isDarkMode}
            onChange={onThemeToggle}
            aria-label="Toggle dark mode"
        >
            {({ isSelected }) => (
                <HeroSwitch.Content>
                    <HeroSwitch.Control>
                        <HeroSwitch.Thumb>
                            <HeroSwitch.Icon>
                                {isSelected ? <MoonIcon className="size-5 text-inherit" /> : <SunIcon className="size-5 text-inherit" />}
                            </HeroSwitch.Icon>
                        </HeroSwitch.Thumb>
                    </HeroSwitch.Control>
                </HeroSwitch.Content>
            )}
        </HeroSwitch>
    </Box>
)

"use client"

import React, { useMemo } from "react"
import {
    useTranslations,
} from "next-intl"
import type { WithClassNames } from "@/modules/types/base/class-name"
import {
    _ProgrammingLanguageTabs,
    DEFAULT_PROGRAMMING_LANGUAGES,
    isProgrammingLangAvailable,
    ProgrammingLanguageTabsVariant,
    programmingLanguageIconMap,
    type ProgrammingLanguageTabItem,
} from "./component"

export { ProgrammingLanguageTabsVariant, programmingLanguageIconMap }

/** Props the connected {@link ProgrammingLanguageTabs} takes from its caller. */
export interface ProgrammingLanguageTabsConnectedProps extends WithClassNames<undefined> {
    /** Language keys returned by the backend (subset of the default four). */
    availableLangs: Array<string>
    /** Controlled selected language key (normalized by `resolveActiveProgrammingLang`). */
    selectedLang: string
    /** Fired when the user selects an enabled tab. */
    onSelectLang: (lang: string) => void
    /** Accessible name for the tab list. */
    ariaLabel: string
    /** When true, always render four tabs even if `availableLangs` is empty. */
    alwaysShow?: boolean
    /** Tab chrome: compact pills or full-width underline tabs. */
    variant?: ProgrammingLanguageTabsVariant
    /** When false with `Secondary`, skip the full-width `border-b` wrapper. */
    surfaceBorder?: boolean
}

/**
 * Fixed four-tab programming-language switcher — the CONNECTED half:
 * resolves each tab's label via `t()`. See `design/storybook/architecture/split.md`.
 *
 * @param props - {@link ProgrammingLanguageTabsConnectedProps}
 */
export const ProgrammingLanguageTabs = ({
    availableLangs,
    ...props
}: ProgrammingLanguageTabsConnectedProps) => {
    const t = useTranslations()

    const tabItems = useMemo<Array<ProgrammingLanguageTabItem>>(
        () => DEFAULT_PROGRAMMING_LANGUAGES.map((lang) => ({
            lang,
            isDisabled: !isProgrammingLangAvailable(lang, availableLangs),
            label: t(`programmingLanguage.${lang}`),
        })),
        [availableLangs, t],
    )

    return <_ProgrammingLanguageTabs {...props} tabItems={tabItems} />
}

"use client"

import React from "react"
import type { ReactNode } from "react"
import { Breadcrumbs, cn } from "@heroui/react"
import { BackLink } from "@/components/blocks/navigation/BackLink"
import { HideAbove } from "@/components/frames/HideAbove"

/** Collapse the full trail into a single "Back" once the path is this deep. */
const LONG_TRAIL_MIN = 4

/** One crumb in a {@link ResponsiveBreadcrumb} trail. */
export interface ResponsiveBreadcrumbItem {
    /** Stable key for the list. */
    key: string | number
    /** Crumb label. */
    label: ReactNode
    /** Navigate handler — omit on the current (last, read-only) crumb. */
    onPress?: () => void
}

/** Props for {@link ResponsiveBreadcrumb}. */
export interface ResponsiveBreadcrumbProps {
    /** The full trail, root → current (current last, usually without `onPress`). */
    items: Array<ResponsiveBreadcrumbItem>
}

/**
 * Breadcrumb for a `PageHeader` `breadcrumb` slot. Shows the full
 * `Home › … › Current` trail on desktop when short; collapses to a single
 * {@link BackLink} ("Back") on mobile, or whenever the trail is long
 * (`>= {@link LONG_TRAIL_MIN}` crumbs) — a long trail wraps and eats vertical
 * space, and deep ancestors are already reachable from top nav. The back
 * target is the deepest clickable ancestor (last item with `onPress`). Pure
 * CSS for the mobile breakpoint; length check is render-time.
 *
 * @param props - {@link ResponsiveBreadcrumbProps}
 * @see Story: .storybook/stories/blocks/navigation/ResponsiveBreadcrumb/ResponsiveBreadcrumb.stories
 */
export const ResponsiveBreadcrumb = ({
    items}: ResponsiveBreadcrumbProps) => {
    // back target = deepest ancestor we can navigate to (skips the current crumb)
    const parent = [...items].reverse().find((item) => item.onPress)
    const isLongTrail = items.length >= LONG_TRAIL_MIN
    const onBack = parent?.onPress

    return (
        <>
            {/* desktop + short trail: the full path */}
            <Breadcrumbs
                className={cn(isLongTrail ? "hidden" : "hidden @app-sm:flex")}
            >
                {items.map((item) => (
                    <Breadcrumbs.Item key={item.key} onPress={item.onPress}>
                        {item.label}
                    </Breadcrumbs.Item>
                ))}
            </Breadcrumbs>

            {/* mobile, or long trail on any width: single "Back" */}
            {onBack ? (
                isLongTrail ? (
                    <BackLink onPress={onBack} />
                ) : (
                    <HideAbove at="sm" body={() => <BackLink onPress={onBack} />} />
                )
            ) : null}
        </>
    )
}

export default ResponsiveBreadcrumb
